// Shared demo fixture (generated by website/tools/demo_fixture/build.mjs, contract section 8).
// The same JSON feeds the teacher app (lib/di/demo_fixture.g.dart) so ids and names match.
import type { Seed } from "./index";
import type { Row } from "./types";
import { core } from "./core";
import fixture from "./demo_fixture.json";

type Rec = Record<string, unknown>;
export const fx = fixture as unknown as {
  school: Rec; classes: (Rec & { id: string; grade: string; section: string; studentCount: number })[]; staff: (Rec & { id: string; name: string })[];
  assignments: (Rec & { classId: string; subject: string; teacherId: string })[]; students: (Rec & { id: string; classId: string; grade: string; section: string; roll: number; name: string; grn: string })[];
  periods: Rec[]; substitutions: Rec[]; exm_candidates: (Rec & { id: string; studentId: string; cls: string; grade: string; section: string })[];
  paperClassIds: Record<string, string[]>; rosteredClassIds: string[];
};

const SECTION_POOL = ["A", "B", "C", "D"];
const rostered = new Set(fx.rosteredClassIds);

/** Existing admin students that sit in a rostered class-section move to the first unrostered section of the same grade. */
function reassign(grade: string, section: string) {
  if (!rostered.has(`cls_${grade}${section}`)) return section;
  return SECTION_POOL.find((s) => !rostered.has(`cls_${grade}${s}`)) ?? section;
}

const existing = (core.students as Rec[]).map((s) => {
  const grade = String(s.grade);
  const section = reassign(grade, String(s.section));
  return { ...s, grade, section, classId: `cls_${grade}${section}` } as unknown as Rec & { id: string; classId: string };
});
const rollNo: Record<string, number> = {};
const students: Row[] = [
  ...existing.map((s) => ({ ...s, roll: (rollNo[s.classId] = (rollNo[s.classId] ?? 0) + 1) })),
  ...fx.students,
] as Row[];

const fixtureStaffIds = new Set(fx.staff.map((s) => s.id));
const staff: Row[] = [
  ...(core.staff as Rec[]).map((s) => ({ ...s, ...(fx.staff.find((f) => f.id === s.id) ?? {}) })),
  ...fx.staff.filter((f) => !(core.staff as Rec[]).some((s) => s.id === f.id)),
].sort((a, b) => String((a as Rec).id).localeCompare(String((b as Rec).id))) as Row[];
void fixtureStaffIds;

/** teacher for a (class, subject) from the fixture assignments; falls back to the first staff of a department */
export const teacherFor = (classId: string, subject: string) => {
  const a = fx.assignments.find((x) => x.classId === classId && x.subject === subject);
  const id = a?.teacherId ?? "stf_023";
  return { teacherId: id, teacher: String((staff.find((s) => (s as Rec).id === id) as Rec | undefined)?.name ?? "") };
};
export const classSize = (classId: string) => fx.classes.find((c) => c.id === classId)?.studentCount ?? 30;

// Empty-but-declared collections so the teacher/parent contract collections exist from day one.
export const demo: Seed = {
  school: [{ ...(core.school[0] as Rec), ...fx.school } as Row],
  students,
  staff,
  classes: fx.classes as unknown as Row[],
  assignments: fx.assignments as unknown as Row[],
  ops_periods: fx.periods as unknown as Row[],
  ops_substitutions: fx.substitutions as unknown as Row[],
};
